B.ni={"King Salmon":0,"Coho (Silver) Salmon":1,"Sockeye (Red) Salmon":2,"Pink (Humpy) Salmon":3,"Chum (Dog) Salmon":4,"Rainbow/Steelhead Trout":5,"Arctic Char / Dolly Varden":6,"Arctic Grayling":7,"Lake Trout":8,Burbot:9,"Northern Pike (Invasive)":10,Whitefish:11,"Other Finfish":12}
B.JS=new A.q(1,0.7529411764705882,0.3215686274509804,0.2901960784313726,B.e)
